cd /tmp/vally-eval-trial-bzDic6 && P=.copilot-tracking/skraft-plans/pricing && D=2026-10-18 && mkdir -p $P/features $P/details/$D $P/evidence/$D/discount tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $P/features/checkout-pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: every scenario below carries an expected value from the approved acceptance criteria.
  # NOT DECIDED: Platinum tier. The business has not agreed a reduction, so there is NO scenario,
  # NO expected value and NO test for it. Do not invent one. Escalated to DISCUSS (see test plan).

  @happy-path @smoke
  Scenario: Bronze customer is charged 9500 cents on a 10000 cent basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged 9000 cents on a 10000 cent basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged 8500 cents on a 10000 cent basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer on a 7 cent basket is charged 7 cents
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class LoyaltyDiscountAcceptanceTests
{
    // Bronze customer is charged 9500 cents on a 10000 cent basket
    [Fact]
    public void Bronze_customer_is_charged_9500_cents_on_a_10000_cent_basket()
    {
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $P/evidence/$D/discount/acceptance-red.stdout 2>&1; echo $? > $P/evidence/$D/discount/acceptance-red.exit; git rev-parse HEAD > $P/evidence/$D/discount/acceptance-red.rev; cat $P/evidence/$D/discount/acceptance-red.exit; tail -25 $P/evidence/$D/discount/acceptance-red.stdout

